"""Report grid-only diagnostic comparisons, including invalid hydrographs."""
import json
from pathlib import Path
import numpy as np,pandas as pd
import plotly.graph_objects as go
from plotly.subplots import make_subplots
import broad_study as b
from test_segmentation48 import OUT,BASE,N
rows=[json.loads(p.read_text()) for p in sorted(OUT.glob('*/result.json'))];assert len(rows)==10
for x in rows:
 a=x['audit'];cap=x['max_dt'];x['verified_exact_constant_steps']=bool(abs(a['min_step_s']-cap)<1e-8 and a['max_step_s']==cap and a['steps']==613920/cap)
assert all(x['verified_exact_constant_steps'] for x in rows if x['max_dt']==.5)
b.save(OUT/'all_results.json',rows)
labels={('shift161',.5):'Shift cells in reach 161 / 0.5 s',('count161',.5):'Reach 161: extra uniform cell / 0.5 s',('baseline',.5):'50 m baseline / 0.5 s',('split79',.5):'Split reach 79 / 0.5 s',('baseline',150):'50 m baseline / adaptive dt',('baseline',1):'50 m baseline / 1 s',('split79',150):'Split reach 79 / adaptive dt',('split79',1):'Split reach 79 / dt capped at 1 s',('shift161',1):'Shift cells in reach 161 / dt capped at 1 s',('count161',1):'Reach 161: one extra uniform cell / 1 s'}
colors=['#111111','#0072B2','#E69F00','#009E73','#D55E00','#CC79A7','#56B4E9','#882255','#332288','#44AA99']
fig=make_subplots(rows=2,cols=2,subplot_titles=['Outlet hydrographs (clipped runs are invalid)','Early event — before and during instability onset','Artificial water added by depth clipping','Maximum depth by physical reach'],vertical_spacing=.16,horizontal_spacing=.10)
force=b.forcing('48');origin=force.interval_start_utc.iloc[0]
def addwave(w,label,color,dash='solid'):
 t=(w.time_utc-origin).dt.total_seconds().to_numpy()/3600;q=w.q_outlet_cms.to_numpy()
 for col,mask in [(1,np.ones(len(t),bool)),(2,(t>=20)&(t<=38))]:
  xx=t[mask];yy=q[mask];ii=set()
  for i in range(0,len(xx),5):ii.update([i+np.argmin(yy[i:i+5]),i+np.argmax(yy[i:i+5])])
  idx=sorted(ii);fig.add_trace(go.Scatter(x=xx[idx],y=yy[idx],name=label,legendgroup=label,showlegend=col==1,line=dict(color=color,dash=dash)),row=1,col=col)
addwave(pd.read_parquet(b.OUT/'investigation/current_mc/states/48/S000_base/outlet.parquet'),'Current MC','#888888','dash')
addwave(pd.read_parquet(b.OUT/'investigation/input_sensitivity48/baseline_dx100_cfl0.35/wave.parquet'),'100 m reference','#999933','dot')
for r,color in zip(rows,colors):
 label=labels[r['variant'],r['max_dt']];folder=Path(r['folder']);addwave(pd.read_parquet(folder/'wave.parquet'),label,color);x=np.load(folder/'event_output.npz');fig.add_trace(go.Scatter(x=x['wave'][::5,0]/3600,y=x['wave'][::5,5]/1e6,name=label,legendgroup=label,showlegend=False,line=dict(color=color)),row=2,col=1)
 cells=pd.read_parquet(folder/'cells.parquet');cells['hmax']=x['hmax'];hm=cells.groupby('id_link').hmax.max();fig.add_trace(go.Scatter(x=hm.index,y=hm.values,name=label,legendgroup=label,showlegend=False,line=dict(color=color)),row=2,col=2)
for col in [1,2]:fig.update_xaxes(title_text='Hours from forcing start',row=1,col=col);fig.update_yaxes(title_text='Outlet discharge (m³/s)',row=1,col=col)
fig.update_xaxes(title_text='Hours from forcing start',row=2,col=1);fig.update_yaxes(title_text='Artificial water (million m³)',row=2,col=1);fig.update_xaxes(title_text='Physical reach ID (not downstream distance)',row=2,col=2);fig.update_yaxes(title_text='Maximum depth (m)',row=2,col=2)
fig.update_layout(template='plotly_white',title='Example 48: isolated segmentation and timestep tests',height=1100,width=1500,legend=dict(orientation='h',y=-.18),margin=dict(b=180),hovermode='x unified');fig.write_html(OUT/'segmentation_plotly.html',include_plotlyjs=True)
b.save(OUT/'plot_expected.json',dict(traces=len(fig.data),subplots=4))
lines=['Example 48 — isolated segmentation and timestep tests','','SCOPE','Original local-inertial update and critical-flow cap, normal-flow outlet, fixed n='+str(N)+'. No calibration or production-data edits. Full reference event; no collapse reruns. Widths, physical reach lengths, endpoint elevations, topology, roughness and forcing unchanged. Every variant independently equilibrated to maximum cell flow imbalance / inlet Q <1e-8. Spinup clipping is recorded separately.','', 'TEST DESIGN','All grids have a maximum 50 m cell length. Baseline has 2824 cells and shortest cell 22.2692877119 m (reach 79).','Split79: only reach 79 is split into two 11.13464385595 m cells. Baseline and split79 each run with adaptive CFL .35, then both with 1 s and 0.5 s caps. The adaptive runs are NOT exactly timestep-matched; the split79 1 s cap run also occasionally uses shorter CFL-limited steps. The 0.5 s pair is verified exactly timestep-matched.','Shift161: replace its 333 equal 49.8570567194 m cells with 334 cells: two endpoint half-cells of 24.9285283597 m and 332 interior cells of 49.8570567194 m. This shifts interior interfaces half a cell while preserving total length and linear bed profile.','Count161 control: 334 equal cells of 49.7077840945 m in reach 161. This distinguishes the shifted pattern from simply adding a cell.','All four grid variants take exactly 0.5 s steps throughout in the additional matched comparisons. The preliminary 1 s cap did not provide exact matching for every variant. Minimum dt, maximum dt and step counts verify these matches. These spatial comparisons do not confound different timestep schedules.','', 'RESULTS','Case | cells | shortest m | first clipping sample h | artificial water million m3 | maximum depth m | peak outlet m3/s']
for r in rows:
 a=r['audit'];lines.append(f"{labels[r['variant'],r['max_dt']]} | {r['cell_count']} | {r['minimum_length_m']:.6f} | {r['first_clipping_sample_hours']} | {a['clipping_volume_m3']/1e6:.6f} | {a['maximum_depth_m']:.6f} | {r['peak_outlet_cms']:.6f}")
lines+=['', 'CAUTION','Clipping adds artificial water. A run with clipping is an invalid hydrograph, even if its water-balance residual after subtracting that clipping is small. Peak values from invalid runs are diagnostics, not valid flood predictions. Their differences cannot rank physical accuracy. First-clipping times are sampled at forcing output intervals, not exact first failing substeps.','All cases start from independently equilibrated states appropriate to their grid. Tiny floating-point and steady-state differences can affect later unstable trajectories; the robust comparison is whether failure persists, not which chaotic spike is tallest.','The shift161 test changes endpoint control-volume sizes and reach-interface face distances, as necessarily follows from the new cell layout. It preserves physical endpoint elevations but is not a test with identical discrete junction operators.','This set does not validate all other networks or test a full shallow-water network solver.']
lines+=['', 'INTERPRETATION', 'All ten event runs clip negative depths. All four exactly matched 0.5 s runs first register clipping in the same output interval, 32.7333 hours from forcing start. Splitting reach 79 and changing the cell arrangement/count in reach 161 therefore do not resolve this failure, nor materially move its sampled onset under a matched timestep.', 'Reducing the baseline timestep from adaptive CFL .35 to fixed 1 s and then 0.5 s delays sampled onset from 31.8 to 32.5667 to 32.7333 hours and reduces artificial water from 35.4352 to 13.5437 to 9.3703 million m3, but failure remains. This is timestep sensitivity, not evidence of a converged stable solution.', 'These tests do not prove that short cells can never matter. They show that the particular shortest cell and the tested grid alignment in reach 161 do not provide a segmentation-only remedy. Together with the previously saved straight-channel full-SWE versus local-inertial benchmark, the results continue to support a broader high-Froude/local-inertial formulation limitation under these assumed hydraulics. No production settings are changed.']
(OUT/'findings.txt').write_text('\n'.join(lines)+'\n');b.save(OUT/'source_manifest.json',{str(p):b.sha(p) for p in [BASE,Path(__file__),Path(__file__).with_name('test_segmentation48.py'),Path(__file__).with_name('inertial_verification_kernel.py')]});print('traces',len(fig.data));print('\n'.join(lines[15:]))
